parts.openscad_module:
// Knurled adjustment knob - OpenSCAD
// Units: mm

$fn = 96;

knob_d = 30;
knob_h = 18;
stem_d = 16;
stem_h = 7;
thread_d = 8;
thread_h = 20;
thread_pitch = 1.25;

bore_d = 8;         // central bore diameter for shaft or insert
grip_count = 42;    // number of knurl ridges
knurl_depth = 1.0;
knurl_count = grip_count;
knurl_angle = 35;
knurl_width = 1.2;

module diamond_knurl_band(d=30, h=18) {
    difference() {
        cylinder(d=d, h=h);
        for (dir = [-1, 1]) {
            for (i = [0:grip_count-1]) {
                rotate([0, 0, i * 360 / knurl_count])
                    translate([d/2 - knurl_depth/2, 0, h/2])
                        rotate([0, dir * knurl_angle, 0])
                            cube([knurl_depth * 3, knurl_width, h * 2.0], center=true);
            }
        }
    }
}

module external_thread(d=8, pitch=1.25, length=20, depth=0.45) {
    turns = length / pitch;
    steps = ceil(turns * 32);
    union() {
        cylinder(d=d - depth, h=length);
        for (i = [0:steps-1]) {
            z1 = i * length / steps;
            z2 = (i + 1) * length / steps;
            a1 = i * 360 / 32;
            a2 = (i + 1) * 360 / 32;
            hull() {
                rotate([0, 0, a1])
                    translate([d/2 - depth, 0, z1])
                        sphere(r=depth, $fn=12);
                rotate([0, 0, a2])
                    translate([d/2 - depth, 0, z2])
                        sphere(r=depth, $fn=12);
            }
        }
    }
}

module knurled_adjustment_knob() {
    difference() {
        union() {
            translate([0, 0, thread_h + stem_h])
                diamond_knurl_band(knob_d, knob_h);
            translate([0, 0, thread_h])
                cylinder(d=stem_d, h=stem_h);
            external_thread(thread_d, thread_pitch, thread_h);
        }
        // Central bore for shaft or threaded insert
        cylinder(h=knob_h + stem_h + thread_h + 2, d=bore_d);
    }
}

knurled_adjustment_knob();
